// ── Validate webhook payload from Evolution API ──
const body = $input.first().json.body || $input.first().json;

// Ignore non-message events (receipts, status updates, etc.)
if (!body?.data?.message) {
  return [{ json: { skip: true, reason: 'not_a_message' } }];
}

const msg = body.data;
const messageType = msg.messageType || 'conversation';

// Only handle text messages
if (!['conversation','extendedTextMessage'].includes(messageType)) {
  return [{ json: { skip: true, reason: 'unsupported_type', type: messageType } }];
}

// Extract message content
const text =
  msg.message?.conversation ||
  msg.message?.extendedTextMessage?.text ||
  '';

if (!text.trim()) {
  return [{ json: { skip: true, reason: 'empty_message' } }];
}

// Ignore own outgoing messages (Evolution echoes them)
if (msg.key?.fromMe === true) {
  return [{ json: { skip: true, reason: 'own_message' } }];
}

// Parse phone number (Evolution sends JID: 1234567890@s.whatsapp.net)
const rawJid = msg.key?.remoteJid || '';
const phone = '+' + rawJid.replace('@s.whatsapp.net', '').replace('@g.us', '');

return [{
  json: {
    skip: false,
    phone,
    messageId: msg.key?.id,
    text: text.trim(),
    instanceName: body.instance || 'default',
    timestamp: msg.messageTimestamp || Math.floor(Date.now() / 1000)
  }
}];

// ── Build the full prompt for GPT-4.1 ──

const contact    = $('node_load_contact').item.json;
const history    = $('node_load_history').all().map(h => h.json);
const portfolio  = $('node_load_portfolio').all().map(p => p.json);
const incoming   = $('node_validate').item.json;
const yourName   = $env.YOUR_NAME || 'Alex';

// ── Tone definitions per contact type ──
const TONES = {
  friend: `You are ${yourName}. You are chatting with a close friend. Keep it casual, warm, and real. Use contractions freely. Match their energy. Be witty when appropriate. Keep replies concise unless the conversation calls for depth. Don't start every message with their name.`,
  family: `You are ${yourName}. You are talking with a family member. Be loving, warm, and attentive. Check in genuinely. Offer help naturally. Keep a caring tone without being patronizing.`,
  client: `You are ${yourName}, a professional developer and consultant. You are speaking with a potential or existing client. Be confident, clear, and professional—but still warm and human. Highlight relevant experience when appropriate. Use their name occasionally. Gently guide conversations toward understanding their needs.`,
  unknown: `You are ${yourName}. Someone new has messaged you. Be friendly and curious, but slightly reserved. Try to understand who they are and what they need without being interrogative. Keep replies brief until context is clear.`
};

const contactType = contact.tone_override || contact.contact_type || 'unknown';
const tonePrompt  = TONES[contactType] || TONES.unknown;

// ── Portfolio context (only for clients) ──
let portfolioContext = '';
if (contactType === 'client' && portfolio.length > 0) {
  portfolioContext = '\n\n## Your Professional Context\nUse the following information naturally in conversation when relevant. Don\'t dump it all at once—weave it in naturally.\n';
  portfolio.forEach(p => {
    portfolioContext += `\n### ${p.title}\n${p.content}\n`;
  });
}

// ── Core persona instructions ──
const systemPrompt = `${tonePrompt}

## Core Rules
- You ARE ${yourName}. Never admit you are an AI under any circumstances unless explicitly instructed to in a separate trigger message.
- Reply naturally, like a real human texting. Keep messages readable—not walls of text.
- Ask follow-up questions naturally to keep conversation flowing.
- If you're uncertain about something personal, say you'll check later.
- Match the language/language register the person uses.
- Never use robotic phrases like "Certainly!", "Of course!", "As an AI...".
- If someone asks if you're a bot, deflect naturally ("haha why do you ask?") and change subject.

## Contact Context
- Name: ${contact.display_name || 'Unknown'}
- Type: ${contactType}
- Notes: ${contact.notes || 'none'}

## Escalation Triggers
If the conversation involves ANY of these, respond normally but add a special JSON block at the very end of your reply (after your human message), on a new line, exactly as shown:
- Legal threats or serious disputes
- Medical emergencies
- Urgent business deals ($5000+)
- Relationship crises or emotional emergencies
- Someone asking to speak to you directly/in person urgently

Escalation format (add ONLY if triggered, after your reply):
[ESCALATE:{"reason":"brief reason","urgency":"high"}]${portfolioContext}`;

// ── Build messages array for OpenAI ──
const messages = [
  { role: 'system', content: systemPrompt }
];

// Add conversation history
history.forEach(h => {
  messages.push({ role: h.role, content: h.content });
});

// Add the new incoming message
messages.push({ role: 'user', content: incoming.text });

return [{
  json: {
    messages,
    systemPrompt,
    contactType,
    contactId: contact.id,
    contactName: contact.display_name,
    phone: incoming.phone,
    instanceName: incoming.instanceName,
    originalText: incoming.text
  }
}];

// ── Parse Gemini response and detect escalation triggers ──

const candidate = $json.candidates?.[0];
const aiRaw = candidate?.content?.parts?.[0]?.text || '';
const tokensUsed = ($json.usageMetadata?.promptTokenCount || 0) + ($json.usageMetadata?.candidatesTokenCount || 0);
const promptData = $('node_build_prompt').item.json;

// Check for escalation block
const escalateMatch = aiRaw.match(/\[ESCALATE:(\{.*?\})\]/s);
const needsEscalation = !!escalateMatch;
let escalationData = null;
if (escalateMatch) {
  try { escalationData = JSON.parse(escalateMatch[1]); } catch(e) {}
}

// Clean reply — remove escalation JSON block from user-facing message
const cleanReply = aiRaw
  .replace(/\[ESCALATE:\{.*?\}\]/s, '')
  .trim();

// Split long replies into chunks (WhatsApp ~1500 char limit per message)
const MAX_LEN = 1500;
const chunks = [];
if (cleanReply.length <= MAX_LEN) {
  chunks.push(cleanReply);
} else {
  const paras = cleanReply.split(/\n\n+/);
  let current = '';
  paras.forEach(p => {
    if ((current + '\n\n' + p).length > MAX_LEN && current) {
      chunks.push(current.trim());
      current = p;
    } else {
      current = current ? current + '\n\n' + p : p;
    }
  });
  if (current) chunks.push(current.trim());
}

// Model name for DB logging
const modelUsed = $env.GEMINI_MODEL || 'gemini-2.0-flash';

return [{
  json: {
    ...promptData,
    aiReply: cleanReply,
    chunks,
    tokensUsed,
    model: modelUsed,
    needsEscalation,
    escalationData
  }
}];

